package com.bank.compensation.service;

import com.bank.compensation.dto.CompensationReport;
import com.bank.compensation.model.Employee;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;
import java.util.stream.Collectors;

@Service
@Slf4j
public class CompensationAnalyticsService {

    private final List<Employee> employees = List.of(
        new Employee("E001", "Rajesh Kumar",  "TRADING",    "M", 35, new BigDecimal("1200000")),
        new Employee("E002", "Priya Sharma",  "RISK",       "F", 28, new BigDecimal("1000000")),
        new Employee("E003", "Amit Patel",    "TRADING",    "M", 52, new BigDecimal("1500000")),
        new Employee("E004", "Deepa Reddy",   "OPERATIONS", "F", 45, new BigDecimal("900000")),
        new Employee("E005", "Vikram Singh",  "RISK",       "M", 55, new BigDecimal("1800000")),
        new Employee("E006", "Neha Gupta",    "TRADING",    "F", 32, new BigDecimal("1100000")),
        new Employee("E007", "Suresh Iyer",   "OPERATIONS", "M", 58, new BigDecimal("1400000")),
        new Employee("E008", "Kavita Joshi",  "RISK",       "F", 41, new BigDecimal("950000")),
        new Employee("E009", "Rohit Mehta",   "COMPLIANCE", "M", 48, new BigDecimal("1300000")),
        new Employee("E010", "Anita Desai",   "COMPLIANCE", "F", 37, new BigDecimal("1050000"))
    );

    public CompensationReport generateReport() {

        // ═══ 1. AVERAGE AGE by gender (overall) ═══
        Map<String, Double> avgAgeByGender = employees.stream()
            .collect(Collectors.groupingBy(Employee::gender,
                Collectors.averagingInt(Employee::age)));
        log.info("Avg age by gender: {}", avgAgeByGender);

        // ═══ 2. AVERAGE SALARY by gender (overall) ═══
        Map<String, Double> avgSalaryByGender = employees.stream()
            .collect(Collectors.groupingBy(Employee::gender,
                Collectors.averagingDouble(e -> e.salary().doubleValue())));
        log.info("Avg salary by gender: {}", avgSalaryByGender);

        // ═══ 3. AVERAGE SALARY per department per gender ═══
        Map<String, Map<String, Double>> perDeptGender = employees.stream()
            .collect(Collectors.groupingBy(Employee::department, TreeMap::new,
                Collectors.groupingBy(Employee::gender,
                    Collectors.averagingDouble(e -> e.salary().doubleValue()))));
        log.info("Avg salary per dept per gender: {}", perDeptGender);

        // ═══ 4. SUMMARY STATISTICS by gender (count, sum, min, avg, max) ═══
        Map<String, DoubleSummaryStatistics> rawStats = employees.stream()
            .collect(Collectors.groupingBy(Employee::gender,
                Collectors.summarizingDouble(e -> e.salary().doubleValue())));

        Map<String, Map<String, String>> summaryStats = new LinkedHashMap<>();
        rawStats.forEach((gender, stats) -> {
            Map<String, String> details = new LinkedHashMap<>();
            details.put("count", String.valueOf((long) stats.getCount()));
            details.put("avgSalary", formatAmount(stats.getAverage()));
            details.put("minSalary", formatAmount(stats.getMin()));
            details.put("maxSalary", formatAmount(stats.getMax()));
            details.put("totalSalary", formatAmount(stats.getSum()));
            summaryStats.put(gender, details);
        });
        log.info("Summary stats: {}", summaryStats);

        // ═══ 5. PAY GAP ANALYSIS ═══
        double maleAvg = avgSalaryByGender.getOrDefault("M", 0.0);
        double femaleAvg = avgSalaryByGender.getOrDefault("F", 0.0);
        double gap = ((maleAvg - femaleAvg) / maleAvg) * 100;
        String payGap = String.format("Male avg: Rs.%.0f | Female avg: Rs.%.0f | Gap: %.1f%% %s",
            maleAvg, femaleAvg, Math.abs(gap),
            gap > 5 ? "(Caution) SIGNIFICANT" : "(Recommended) WITHIN RANGE");

        return new CompensationReport(avgAgeByGender, avgSalaryByGender,
            perDeptGender, summaryStats, payGap);
    }

    private String formatAmount(double amount) {
        return "Rs." + BigDecimal.valueOf(amount).setScale(0, RoundingMode.HALF_UP);
    }
}
