package com.bank.compensation.service;

import com.bank.compensation.model.Employee;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.*;

class AverageCalculationTest {

    List<Employee> emps = List.of(
        new Employee("E1", "Rajesh", "TRADING", "M", 30, BigDecimal.valueOf(1000000)),
        new Employee("E2", "Priya", "TRADING", "F", 28, BigDecimal.valueOf(800000)),
        new Employee("E3", "Amit", "RISK", "M", 40, BigDecimal.valueOf(1200000)),
        new Employee("E4", "Deepa", "RISK", "F", 35, BigDecimal.valueOf(900000))
    );

    @Test
    void avgAgeByGender() {
        Map<String, Double> avg = emps.stream()
            .collect(Collectors.groupingBy(Employee::gender,
                Collectors.averagingInt(Employee::age)));
        assertThat(avg.get("M")).isEqualTo(35.0);  // (30+40)/2
        assertThat(avg.get("F")).isEqualTo(31.5);  // (28+35)/2
    }

    @Test
    void avgSalaryByGender() {
        Map<String, Double> avg = emps.stream()
            .collect(Collectors.groupingBy(Employee::gender,
                Collectors.averagingDouble(e -> e.salary().doubleValue())));
        assertThat(avg.get("M")).isEqualTo(1100000.0);  // (1M+1.2M)/2
        assertThat(avg.get("F")).isEqualTo(850000.0);   // (800K+900K)/2
    }

    @Test
    void avgSalaryPerDeptPerGender() {
        Map<String, Map<String, Double>> result = emps.stream()
            .collect(Collectors.groupingBy(Employee::department,
                Collectors.groupingBy(Employee::gender,
                    Collectors.averagingDouble(e -> e.salary().doubleValue()))));
        assertThat(result.get("TRADING").get("M")).isEqualTo(1000000.0);
        assertThat(result.get("RISK").get("F")).isEqualTo(900000.0);
    }

    @Test
    void summarizingDoubleGivesFullStats() {
        DoubleSummaryStatistics stats = emps.stream()
            .filter(e -> "M".equals(e.gender()))
            .collect(Collectors.summarizingDouble(e -> e.salary().doubleValue()));
        assertThat(stats.getCount()).isEqualTo(2);
        assertThat(stats.getMin()).isEqualTo(1000000.0);
        assertThat(stats.getMax()).isEqualTo(1200000.0);
        assertThat(stats.getAverage()).isEqualTo(1100000.0);
    }
}
